/** Event text and choices are unchanged. The result receives a special CG only after the ending flag is awarded. */
export function getEncounterArt(eventId: string, flags: readonly string[] = [], resultShown = false): ArtEntry | undefined {
  if (resultShown) {
    for (const npc of ["rael", "seon", "kairu"] as const) {
      const finalId = npc === "rael" ? "rael_final" : `${npc}_final_choice`;
      if (eventId === finalId) {
        if (flags.includes(`route_${npc}_happy`)) {
          if (flags.includes(`romance_${npc}_promise`)) return getEndingArt(`${npc}_romance`);
          return getEndingArt(`${npc}_route_happy`);
        }
      }
    }
  }
  const id = EVENT_ART[eventId];
  return id ? byId.get(id) : undefined;
}
export function getEndingArt(endingId: string): ArtEntry | undefined {
  const id = ENDING_ART[endingId];
  return id ? byId.get(id) : undefined;
}
export function getShopArt(shopItemId: string): ArtEntry | undefined {
  const id = SHOP_ART[shopItemId];
  return id ? byId.get(id) : undefined;
}
export function getArt(id: string): ArtEntry | undefined { return byId.get(id); }
export function artIsUnlocked(art: ArtEntry, endings: ReadonlySet<string>, discovered: ReadonlySet<string> = new Set()): boolean {
  return discovered.has(art.id) || Boolean(art.unlock && endings.has(art.unlock));
}
